// 1) DOM interaction
function LoginField() {
  const inputRef = useRef(null);
  useEffect(() => { inputRef.current?.focus(); }, []);
  return <input ref={inputRef} name="email" />;
}

// 2) Mutable value that must NOT cause re-renders
function SaveTimer() {
  const lastSavedAt = useRef(null);
  const controllerRef = useRef(null);            // AbortController across renders

  async function save() {
    controllerRef.current?.abort();              // cancel the previous in-flight save
    controllerRef.current = new AbortController();
    await api.save(payload, { signal: controllerRef.current.signal });
    lastSavedAt.current = Date.now();            // no re-render — and we don't want one
  }
  return <button onClick={save}>Save</button>;
}

// 3) Latest-ref pattern: long-lived listener reads fresh values without re-subscribing
function useHotkeys(handler) {
  const handlerRef = useRef(handler);
  useEffect(() => { handlerRef.current = handler; });   // updated every render

  useEffect(() => {
    const onKeyDown = (e) => handlerRef.current(e);     // always the newest handler
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);  // registered ONCE
  }, []);
}

// 4) Callback ref for measuring (runs on mount/unmount)
function Measured({ onHeight }) {
  const ref = useCallback((node) => {
    if (node) onHeight(node.getBoundingClientRect().height);
  }, [onHeight]);
  return <section ref={ref}>...</section>;
}

